queries.sphinxql:
create table t (title text, cat int, brand int, j json, vec float_vector knn_type='hnsw' knn_dims='2' hnsw_similarity='l2');
insert into t values (1, 'red apple', 1, 10, '{"x":1}', (0.1,0)), (2, 'red pear', 1, 20, '{"x":2}', (0.2,0)), (3, 'green apple', 2, 10, '{"y":1}', (0.3,0)), (4, 'green pear', 2, 20, '{"x":4}', (1,0)), (5, 'blue plum', 3, 30, '{"y":2}', (2,0));
create table t2 (name string);
insert into t2 values (10, 'acme'), (20, 'bolt'), (30, 'cog');


select id from t where match('red') and knn(vec,5,(0,0)) order by id asc option fusion_method='rrf', ranker=expr('100') facet cat order by facet() asc facet brand order by facet() asc;;
select id from t where match('red') and knn(vec,5,(0,0)) order by id asc limit 1 option fusion_method='rrf', ranker=expr('100') facet cat order by facet() asc;;


select id, weight() from t where match('red') and knn(vec,5,(0,0)) and weight()>10 order by id asc option fusion_method='rrf', ranker=expr('100') facet cat order by facet() asc;;
select id from t where match('red') and knn(vec,5,(0,0)) and knn_dist()<0.5 order by id asc option fusion_method='rrf', ranker=expr('100') facet cat order by facet() asc;;
select id, weight()*10 w from t where match('red') and knn(vec,5,(0,0)) and w>100 order by id asc option fusion_method='rrf', ranker=expr('100') facet cat order by facet() asc;;
select id, weight()*10 w, w+1 w1 from t where match('red') and knn(vec,5,(0,0)) and w1>100 order by id asc option fusion_method='rrf', ranker=expr('100') facet cat order by facet() asc;;


select id from t where match('red') and knn(vec,5,(0,0)) and j.x is null order by id asc option fusion_method='rrf', ranker=expr('100') facet cat order by facet() asc;;
select id from t where match('red') and knn(vec,5,(0,0)) and j.x is not null order by id asc option fusion_method='rrf', ranker=expr('100') facet cat order by facet() asc;;


select id from t where match('red') and knn(vec,5,(0,0)) and (cat=1 or brand=30) order by id asc option fusion_method='rrf', ranker=expr('100') facet brand order by facet() asc;;
select id from t where match('red') and knn(vec,5,(0,0)) and (cat=1 or brand=30) and (brand=10 or brand=30) order by id asc option fusion_method='rrf', ranker=expr('100') facet brand order by facet() asc;;


select id from t where match('red') and knn(vec,5,(0,0)) and cat=1 order by id asc option fusion_method='rrf', ranker=expr('100'), facet_filter_mode='max' facet cat order by facet() asc facet brand order by facet() asc;;
select id from t where match('red') and knn(vec,5,(0,0)) and cat=1 order by id asc option fusion_method='rrf', ranker=expr('100'), facet_filter_mode='auto' facet cat order by facet() asc facet brand order by facet() asc;;
select id from t where match('red') and knn(vec,5,(0,0)) and cat=1 and brand=10 order by id asc option fusion_method='rrf', ranker=expr('100') facet cat order by facet() asc facet brand exclude filters cat order by facet() asc facet brand all filters zeroes mode max order by facet() asc;;
select id from t where match('red') and knn(vec,5,(0,0)) and cat=1 and weight()>10 order by id asc option fusion_method='rrf', ranker=expr('100'), facet_filter_mode='max' facet cat order by facet() asc;;


select cat, count(*) c, max(brand) mb from t where match('red') and knn(vec,5,(0,0)) group by cat order by cat asc option fusion_method='rrf', ranker=expr('100') facet brand order by facet() asc;;


select id, t2.name from t inner join t2 on t.brand=t2.id where match('red') and knn(vec,5,(0,0)) order by id asc option fusion_method='rrf', ranker=expr('100') facet cat order by facet() asc;;
select id, weight()*10 w, t2.name from t inner join t2 on t.brand=t2.id where match('red') and knn(vec,5,(0,0)) and w>100 order by id asc option fusion_method='rrf', ranker=expr('100') facet cat order by facet() asc;;
select id, t2.name from t inner join t2 on t.brand=t2.id where match('red') and knn(vec,5,(0,0)) and t2.name='acme' order by id asc option fusion_method='rrf', ranker=expr('100') facet cat order by facet() asc;;


select id, hybrid_score() from t where match('red') and knn(vec,5,(0,0)) order by hybrid_score() desc, id asc limit 2 option fusion_method='rrf', ranker=expr('100') facet cat order by facet() asc;;
select id, hybrid_score() from t where match('red') and knn(vec,5,(0,0)) order by hybrid_score() desc, id asc limit 2 option fusion_method='rrf', ranker=expr('100'), scroll='eyJvcmRlcl9ieV9zdHIiOiJoeWJyaWRfc2NvcmUoKSBkZXNjLCBpZCBhc2MiLCJvcmRlcl9ieSI6W3siYXR0ciI6Imh5YnJpZF9zY29yZSgpIiwiZGVzYyI6dHJ1ZSwidmFsdWUiOjAuMDIsInR5cGUiOiJmbG9hdCJ9LHsiYXR0ciI6ImlkIiwiZGVzYyI6ZmFsc2UsInZhbHVlIjowLCJ0eXBlIjoiaW50In1dfQ==' facet cat order by facet() asc;;
select id, hybrid_score() from t where match('red') and knn(vec,5,(0,0)) and cat>1 order by hybrid_score() desc, id asc limit 2 option fusion_method='rrf', ranker=expr('100'), facet_filter_mode='max', scroll='eyJvcmRlcl9ieV9zdHIiOiJoeWJyaWRfc2NvcmUoKSBkZXNjLCBpZCBhc2MiLCJvcmRlcl9ieSI6W3siYXR0ciI6Imh5YnJpZF9zY29yZSgpIiwiZGVzYyI6dHJ1ZSwidmFsdWUiOjAuMDIsInR5cGUiOiJmbG9hdCJ9LHsiYXR0ciI6ImlkIiwiZGVzYyI6ZmFsc2UsInZhbHVlIjowLCJ0eXBlIjoiaW50In1dfQ==' facet cat order by facet() asc;;


flush ramchunk t;
select id from t where match('red') and knn(vec,5,(0,0)) and j.x is null order by id asc option fusion_method='rrf', ranker=expr('100') facet cat order by facet() asc;;
select id from t where match('red') and knn(vec,5,(0,0)) and cat=1 order by id asc option fusion_method='rrf', ranker=expr('100'), facet_filter_mode='max' facet cat order by facet() asc facet brand order by facet() asc;;
